def _encode_amount(cents):
    try:
        if cents < 0:
            sign = '-'
            digits = str(-cents)
        else:
            sign = '+'
            digits = str(cents)
        if not digits.isdigit():
            raise ValueError
        check = sum(int(ch) for ch in digits) % 10
        return f"{sign}{digits}#{check}"
    except (TypeError, ValueError):
        raise ledger.PostError("malformed amount")

def record(acct, cents, note):
    amount = _encode_amount(cents)
    return ledger.post(acct, amount, memo=note)

